test("proof threshold per grade scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "3"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20"}));
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
  await ui.setToday(pg_uma, "2026-04-03");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-16"})).toBe(true);
  expect(await ui.watch(pg_uma, p_cam, true)).toBe(true);
  expect(await ui.bulkGrade(pg_uma, [p_ben, p_ada], {"grade": "B"})).toBe(2);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  await ui.refresh(pg_uma);
  await ui.setToday(pg_uma, "2026-04-13");
  expect(await ui.periodAction(pg_uma, "P2", "soft-close")).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Ben,12.50,,a, b\nCam,3.33,2026-02-25,a, b\nAda,7.77,2026-03-15,")).toBe(3);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
  const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
  expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
  await ui.setToday(pg_uma, "2026-05-12");
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "1.00", "date": "2026-03-15", "note": "n", "ref": "R-2", "tags": "a, B"}));
  await ui.refresh(pg_uma);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "20.00", "note": "n"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const c_ben_2 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "7.77", "date": "2026-03-15", "note": "n"}));
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.editInline(pg_uma, c_ben_2, "7.77")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-27")).toBe(true);
  await ui.refresh(pg_uma);

